31	function loadMermaidScript(): Promise<void> {
32	  return new Promise((resolve, reject) => {
33	    if (window.mermaid) {
34	      resolve();
35	      return;
36	    }
37	    const script = document.createElement("script");
38	    script.src = "https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js";
39	    script.async = true;
40	    script.onload = () => {
41	      try {
42	        window.mermaid.initialize({ startOnLoad: false, theme: "default" });
43	        resolve();
44	      } catch (e) {
45	        reject(e);
46	      }
47	    };
48	    script.onerror = () => reject(new Error("Falha ao carregar Mermaid via CDN"));
49	    document.head.appendChild(script);
50	  });
51	}
