69	async function generateMermaidFromDescription(description: string): Promise<string> {
70	  try {
71	    const response = await fetch(`${SUPABASE_URL}/functions/v1/generate-flowchart-ai`, {
72	      method: "POST",
73	      headers: {
74	        "Content-Type": "application/json",
75	        "Authorization": `Bearer ${SUPABASE_ANON_KEY}`,
76	      },
77	      body: JSON.stringify({ description }),
78	    });
79	
80	    if (!response.ok) {
81	      const text = await response.text();
82	      throw new Error(text || `Erro ${response.status}`);
83	    }
84	    const data = await response.json();
85	    return (data?.mermaid || data?.diagram || "").trim();
86	  } catch (e) {
87	    handleError(e, { domain: 'fluxogramas', operation: 'generateMermaidFromDescription', showToast: false });
88	    // Fallback local robusto: quebra por frases e vírgulas chave
89	    const sentences = description
90	      .split(/(?:[.;\n]+|,\s*(?=se|caso|ent[aã]o|quando))/gi)
91	      .map((s) => s.trim())
92	      .filter((s) => s.length > 0);
93	
94	    const steps = sentences.length ? sentences : [description.trim()].filter(Boolean);
95	
96	    const header = "flowchart TD";
97	    const nodes: string[] = ["S([Início])"];
98	    steps.forEach((t, i) => nodes.push(`N${i + 1}["${t.replace(/"/g, '\\"')}"]`));
99	    nodes.push("E([Fim])");
100	
101	    const edges: string[] = [];
102	    if (steps.length === 0) {
103	      edges.push("S-->E");
104	    } else {
105	      edges.push("S-->N1");
106	      for (let i = 1; i < steps.length; i++) {
107	        edges.push(`N${i}-->N${i + 1}`);
108	      }
109	      edges.push(`N${steps.length}-->E`);
110	    }
111	
112	    return [header, ...nodes, ...edges].join("\n");
113	  }
114	}
