359	  // Utilitário: converter rgb(a)/nome para hex simples
360	  function toHexColor(input: string): string {
361	    try {
362	      if (!input) return "#ffffff";
363	      const s = input.trim().toLowerCase();
364	      if (s === "none") return "#ffffff";
365	      if (s.startsWith("#")) {
366	        if (s.length === 4) {
367	          // #rgb -> #rrggbb
368	          const r = s[1];
369	          const g = s[2];
370	          const b = s[3];
371	          return `#${r}${r}${g}${g}${b}${b}`;
372	        }
373	        return s;
374	      }
375	      const m = s.match(/rgba?\(([^)]+)\)/);
376	      if (m) {
377	        const parts = m[1].split(/\s*,\s*/).map(Number);
378	        const [r, g, b] = parts;
379	        const toHex = (n: number) => {
380	          const clamped = Math.max(0, Math.min(255, Math.round(n)));
381	          return clamped.toString(16).padStart(2, "0");
382	        };
383	        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
384	      }
385	      // cores nomeadas simples: delegar ao browser via canvas
386	      const canvas = document.createElement("canvas");
387	      const ctx = canvas.getContext("2d");
388	      if (ctx) {
389	        ctx.fillStyle = s;
390	        const computed = ctx.fillStyle as string;
391	        if (computed && computed !== s) {
392	          const mm = computed.match(/rgba?\(([^)]+)\)/);
393	          if (mm) {
394	            const [rr, gg, bb] = mm[1].split(/\s*,\s*/).map(Number);
395	            const toHex = (n: number) => n.toString(16).padStart(2, "0");
396	            return `#${toHex(rr)}${toHex(gg)}${toHex(bb)}`;
397	          }
398	        }
399	      }
400	      return "#ffffff";
401	    } catch {
402	      return "#ffffff";
403	    }
404	  }
