115	// ── Hex decoder + parse (anti ABNT2) ───────────────────────────────────────
116	function decodeHex(hex: string) {
117	  const bytes = new Uint8Array(hex.length / 2);
118	  for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
119	  return new TextDecoder().decode(bytes);
120	}
