563	export function useEtiquetaScanner({
564	  enabled,
565	  onScan,
566	  onInvalid,
567	  onDuplicate,
568	  cameraElementId = "etiqueta-qr-reader",
569	  initialMode = "bluetooth",
570	}: UseEtiquetaScannerOptions) {
571	  const [scanMode, setScanMode] = useState<ScanMode>(initialMode);
572	  const [scanBuffer, setScanBuffer] = useState("");
573	  const inputRef = useRef<HTMLInputElement>(null);
574	  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
575	  const [cameraActive, setCameraActive] = useState(false);
576	  const [cameraError, setCameraError] = useState<string | null>(null);
577	  const [cameraStarting, setCameraStarting] = useState(false);
578	  const [cameraAttempt, setCameraAttempt] = useState(0);
579	  const retryCamera = useCallback(() => setCameraAttempt((n) => n + 1), []);
580	
581	  /**
582	   * Cooldown anti-repetição por modo:
583	   * - câmera: 3000ms — BarcodeDetector detecta o mesmo QR a 60fps.
584	   *   Sem janela grande, o consumer recebe N toasts por segundo.
585	   * - bluetooth: 1200ms — leitor físico pode reenviar se o operador
586	   *   segurar o gatilho. Janela menor pois não é loop automático.
587	   */
588	  const lastScanRef = useRef<{ value: string; ts: number } | null>(null);
589	  const COOLDOWN_CAMERA_MS = 3000;
590	  const COOLDOWN_BT_MS = 1200;
591	
592	  // Refs pros callbacks e scanMode — permite handleScan (deps=[]) acessar
593	  // valores atuais sem recriar o callback a cada render.
594	  const onScanRef = useRef(onScan);
595	  const onInvalidRef = useRef(onInvalid);
596	  const onDuplicateRef = useRef(onDuplicate);
597	  const scanModeRef = useRef(scanMode);
598	  useEffect(() => {
599	    onScanRef.current = onScan;
600	    onInvalidRef.current = onInvalid;
601	    onDuplicateRef.current = onDuplicate;
602	    scanModeRef.current = scanMode;
603	  });
604	
605	  const handleScan = useCallback(async (raw: string) => {
606	    setScanBuffer("");
607	
608	    const now = Date.now();
609	    const last = lastScanRef.current;
610	    const cooldown = scanModeRef.current === "camera" ? COOLDOWN_CAMERA_MS : COOLDOWN_BT_MS;
611	    if (last && last.value === raw && now - last.ts < cooldown) {
612	      // Mesma leitura dentro da janela — silencia. Câmera detecta 60x/s,
613	      // sem cooldown longo vira spam de toast. onDuplicate só dispara uma
614	      // vez por janela (primeiro hit) via throttle abaixo.
615	      return;
616	    }
617	    lastScanRef.current = { value: raw, ts: now };
618	
619	    const payload = parseQrData(raw);
620	
621	    // Rejeita apenas se o parse falhou COMPLETAMENTE (nem uid nem pid).
622	    // QR novo contém só UID → pid="" mas uid presente: válido, deixa passar.
623	    // QR legado contém pid mas uid vazio: também válido.
624	    // Consumers checam o que precisam (uid ou pid) dentro do próprio onScan.
625	    if (!payload || (!payload.uid && !payload.pid)) {
626	      // Log explícito pra debug em campo (DevTools no tablet/mobile)
627	      // eslint-disable-next-line no-console
628	      console.warn("[useEtiquetaScanner] QR rejeitado", {
629	        raw_len: raw?.length ?? 0,
630	        raw_preview: (raw || "").slice(0, 120),
631	        parsed: payload,
632	      });
633	      // Telemetria remota — admin vê todos os erros agregados, com device info,
634	      // sem precisar pedir log manual pro operador.
635	      const isOnlyHex = /^[0-9a-f]+$/i.test((raw || "").trim());
636	      const isOddLen = (raw?.length ?? 0) % 2 === 1;
637	      wideError("scanner.qr_rejected", "QR não decodificou em payload válido", {
638	        domain: "logistica",
639	        attributes: {
640	          ...getDeviceContext(),
641	          "scan.mode": scanMode,
642	          "raw.len": String(raw?.length ?? 0),
643	          "raw.preview": (raw || "").slice(0, 200),
644	          "raw.is_only_hex": String(isOnlyHex),
645	          "raw.is_odd_len": String(isOddLen),
646	        },
647	      });
648	      // Tabela Supabase (visível em /admin/telemetria-scanner)
649	      void logScannerEvent({
650	        evento: 'qr_rejected',
651	        scan_mode: scanMode,
652	        raw_len: raw?.length ?? 0,
653	        raw_preview: (raw || "").slice(0, 400),
654	        raw_is_only_hex: isOnlyHex,
655	        raw_is_odd_len: isOddLen,
656	      });
657	      playErrorSound();
658	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
659	      onInvalidRef.current?.(raw);
660	      return;
661	    }
662	    // Sucesso — log info-level pra agregar volume e detectar regressões
663	    wideInfo("scanner.qr_scanned", "QR decodificou com sucesso", {
664	      domain: "logistica",
665	      attributes: {
666	        ...getDeviceContext(),
667	        "scan.mode": scanMode,
668	        "scan.uid": payload.uid || "(sem uid)",
669	        "scan.pid": payload.pid,
670	        "raw.len": String(raw?.length ?? 0),
671	      },
672	    });
673	    void logScannerEvent({
674	      evento: 'qr_scanned',
675	      scan_mode: scanMode,
676	      scan_uid: payload.uid || null,
677	      scan_pid: payload.pid,
678	      raw_len: raw?.length ?? 0,
679	      // Persiste raw_preview também em sucesso pra diagnóstico em campo —
680	      // muitas leituras "qr_scanned" no Android Chrome 147 vem com pid OK
681	      // mas uid perdido, e a única forma de entender o que faltou é ver o raw.
682	      raw_preview: (raw || "").slice(0, 400),
683	      raw_is_only_hex: /^[0-9a-f]+$/i.test((raw || "").trim()),
684	      raw_is_odd_len: (raw?.length ?? 0) % 2 === 1,
685	    });
686	    await onScanRef.current(payload, raw);
687	  // Refs garantem que o callback nao precisa ser recriado a cada render do
688	  // consumer (que normalmente passa onScan/onInvalid/onDuplicate inline).
689	  // Sem isso, useEffect da camera/keydown re-roda em loop e camera fica eterna.
690	  // eslint-disable-next-line react-hooks/exhaustive-deps
691	  }, []);
692	
693	  // Bluetooth: foca o input invisível e mantém foco. O input ainda é renderizado
694	  // como fallback (alguns ambientes preferem input field), mas o canal primário
695	  // é o keydown global (abaixo) — bypassa IME do Android e elimina perda por
696	  // foco/blur. Mantemos os dois rodando em paralelo: se o keydown global pegar
697	  // primeiro, o input fica vazio (eventos consumidos via preventDefault opcional).
698	  useEffect(() => {
699	    if (!enabled || scanMode !== "bluetooth") return;
700	    inputRef.current?.focus();
701	    const iv = setInterval(() => {
702	      if (document.activeElement !== inputRef.current && scanMode === "bluetooth") {
703	        inputRef.current?.focus();
704	      }
705	    }, 500);
706	    return () => clearInterval(iv);
707	  }, [enabled, scanMode]);
708	
709	  // CAPTURA GLOBAL via e.code (scancode FÍSICO) — ignora layout do teclado e
710	  // IME do Android completamente. e.key passa pelo InputMethod e em PT-BR/Android
711	  // pode virar char Latin-1 (Alt codes). e.code é o ID físico da tecla
712	  // ("Digit7", "KeyA"), independente de layout.
713	  //
714	  // Confirmado via telemetria: tablet Android com Goldsky enviava bytes 0xd7
715	  // (×), 0xa3 (£), 0xc2 (Â) — Alt codes do PT-BR. Com e.code, esses chars
716	  // viram '7', 'a', 'a' (digitação real) e o JSON parseia.
717	  useEffect(() => {
718	    if (!enabled || scanMode !== "bluetooth") return;
719	
720	    let buffer = "";
721	    let timer: ReturnType<typeof setTimeout> | null = null;
722	
723	    const flush = () => {
724	      const trimmed = buffer.trim();
725	      buffer = "";
726	      if (timer) { clearTimeout(timer); timer = null; }
727	      // Threshold mínimo do UID-only (4 chars, casa com regex em parseQrData).
728	      // Antes era 20 — bloqueava silenciosamente etiquetas no formato canônico
729	      // novo (UID 8 chars), sem console, toast ou telemetria.
730	      if (trimmed.length >= 4) void handleScan(trimmed);
731	    };
732	
733	    /** Converte scancode físico → char real, ignorando layout/IME. */
734	    const codeToChar = (code: string, shift: boolean): string | null => {
735	      // Digits (DigitN → 'N' / shift+N → símbolo). Hex usa só 0-9 sem shift.
736	      const digitMatch = /^Digit([0-9])$/.exec(code);
737	      if (digitMatch) return shift ? null : digitMatch[1];
738	      // Letras (KeyA → 'a'). Hex usa a-f.
739	      const letterMatch = /^Key([A-Z])$/.exec(code);
740	      if (letterMatch) return letterMatch[1].toLowerCase();
741	      // Outros chars de JSON / formato Momma
742	      switch (code) {
743	        case "Minus":     return "-";
744	        case "Period":    return ".";
745	        case "Comma":     return ",";
746	        case "Slash":     return "/";
747	        case "Backslash": return "\\";
748	        case "Quote":     return shift ? '"' : "'";
749	        case "Semicolon": return shift ? ":" : ";";
